def get_ip_geolocation(host: str, timeout: float = 5.0, api_token: str | None = None, prefer_ipv6: bool = False) -> dict:
    """
    Resolve the given host to an IP address and fetch geolocation info from ipinfo.io.

    Returns a dict:
      - success (bool)
      - ip (str or None) : resolved IP address
      - data (dict or None) : parsed geolocation JSON from ipinfo.io (when success)
      - raw (str or None) : raw response text from ipinfo.io (when available)
      - status_code (int or None) : HTTP status code from ipinfo.io (when available)
      - error (str or None) : error message when not successful

    Parameters:
      - host: hostname or IP address (string)
      - timeout: seconds for DNS and HTTP operations
      - api_token: optional ipinfo.io token (if you have one)
      - prefer_ipv6: if True, prefer AAAA records over A records when resolving

    Dependencies:
      - httpx
      - dnspython
    Install: pip install httpx dnspython
    """
    # Local imports so the function is self-contained
    import ipaddress
    import socket
    try:
        import httpx
    except Exception as e:
        return {"success": False, "ip": None, "data": None, "raw": None, "status_code": None,
                "error": f"httpx is required but couldn't be imported: {e}"}
    try:
        import dns.resolver
        import dns.exception
    except Exception as e:
        return {"success": False, "ip": None, "data": None, "raw": None, "status_code": None,
                "error": f"dnspython is required but couldn't be imported: {e}"}

    if not host or not isinstance(host, str):
        return {"success": False, "ip": None, "data": None, "raw": None, "status_code": None,
                "error": "host must be a non-empty string"}

    host = host.strip()

    resolved_ip = None

    # If the input is already an IP, use it directly
    try:
        ip_obj = ipaddress.ip_address(host)
        resolved_ip = str(ip_obj)
    except Exception:
        # Not an IP literal; attempt DNS resolution using dnspython
        resolver = dns.resolver.Resolver()
        # Set both timeout and lifetime to allow quick failures
        try:
            resolver.timeout = float(timeout)
            resolver.lifetime = float(timeout)
        except Exception:
            # ignore if conversion fails; keep defaults
            pass

        query_order = ["AAAA", "A"] if prefer_ipv6 else ["A", "AAAA"]

        dns_errors = []
        for qtype in query_order:
            try:
                answers = resolver.resolve(host, qtype)
                for rdata in answers:
                    candidate = rdata.to_text()
                    # take the first answer
                    resolved_ip = candidate
                    break
                if resolved_ip:
                    break
            except dns.resolver.NoAnswer:
                dns_errors.append(f"No answer for {qtype}")
            except dns.resolver.NXDOMAIN:
                dns_errors.append("Hostname does not exist (NXDOMAIN)")
                break
            except dns.exception.Timeout:
                dns_errors.append("DNS query timed out")
            except dns.resolver.NoNameservers:
                dns_errors.append("No name servers available for domain")
            except Exception as e:
                dns_errors.append(f"DNS resolution error ({qtype}): {e}")

        # If dnspython failed to resolve, attempt a socket fallback
        if not resolved_ip:
            try:
                # getaddrinfo may return IPv6 or IPv4; pick the first address
                infos = socket.getaddrinfo(host, None)
                for info in infos:
                    sockaddr = info[4]
                    candidate = sockaddr[0]
                    # prefer the candidate type according to prefer_ipv6 flag
                    try:
                        ipaddress.ip_address(candidate)  # validate
                        resolved_ip = candidate
                        break
                    except Exception:
                        continue
            except socket.gaierror as e:
                dns_errors.append(f"socket.getaddrinfo error: {e}")
            except Exception as e:
                dns_errors.append(f"socket fallback error: {e}")

        if not resolved_ip:
            return {"success": False, "ip": None, "data": None, "raw": None, "status_code": None,
                    "error": "DNS resolution failed: " + "; ".join(dns_errors)}

    # At this point we have an IP; query ipinfo.io
    ip = resolved_ip
    base_url = f"https://ipinfo.io/{ip}/json"
    if api_token:
        # ipinfo accepts token query parameter
        url = f"{base_url}?token={api_token}"
    else:
        url = base_url

    try:
        resp = httpx.get(url, timeout=timeout)
    except httpx.RequestError as e:
        return {"success": False, "ip": ip, "data": None, "raw": None, "status_code": None,
                "error": f"Network error when contacting ipinfo.io: {e}"}
    except Exception as e:
        return {"success": False, "ip": ip, "data": None, "raw": None, "status_code": None,
                "error": f"Unexpected error when contacting ipinfo.io: {e}"}

    status = resp.status_code
    text = resp.text if resp.text is not None else None

    if status == 429:
        return {"success": False, "ip": ip, "data": None, "raw": text, "status_code": status,
                "error": "ipinfo.io rate-limited the request (HTTP 429). Consider using an API token or retrying later."}
    if status < 200 or status >= 300:
        # try to include any message from the body
        msg = text or f"HTTP {status}"
        return {"success": False, "ip": ip, "data": None, "raw": text, "status_code": status,
                "error": f"ipinfo.io returned non-OK status: {msg}"}

    # Parse JSON safely
    try:
        data = resp.json()
    except ValueError:
        return {"success": False, "ip": ip, "data": None, "raw": text, "status_code": status,
                "error": "ipinfo.io returned invalid JSON"}

    # Success
    return {"success": True, "ip": ip, "data": data, "raw": text, "status_code": status, "error": None}
