Copy-paste this function into your code. It only uses stdlib modules plus optional third-party libraries dnspython and httpx for improved behavior; if those are not installed the function falls back to the stdlib.

def resolve_and_geolocate(host: str,
                          token: str | None = None,
                          timeout: float = 5.0,
                          max_retries: int = 2) -> dict:
    """
    Resolve `host` to an IP address and fetch geolocation info from ipinfo.io.

    Parameters:
    - host: hostname or IP address (IPv4/IPv6)
    - token: optional ipinfo.io token (appended as ?token=TOKEN)
    - timeout: timeout in seconds for network operations
    - max_retries: number of attempts for DNS and HTTP operations (>=1)

    Returns a dict with keys:
    - success: bool
    - ip: resolved IP address (str) or None
    - data: geolocation dict from ipinfo.io on success, else None
    - error: human-readable error string on failure, else None
    - status_code: HTTP status code from ipinfo.io if available, else None

    Example:
    result = resolve_and_geolocate("example.com", token=None)
    if result["success"]:
        print(result["ip"], result["data"])
    else:
        print("Error:", result["error"])
    """
    import time
    import json
    import ipaddress
    from typing import Optional

    # Try to import dnspython resolver; fall back to socket if not present
    try:
        import dns.resolver
        DNSPY_AVAILABLE = True
    except Exception:
        DNSPY_AVAILABLE = False
        import socket

    # Try to import httpx; fall back to urllib if not present
    try:
        import httpx
        HTTPX_AVAILABLE = True
    except Exception:
        HTTPX_AVAILABLE = False
        import urllib.request
        import urllib.error

    if not host:
        return {"success": False, "ip": None, "data": None, "error": "Empty host provided", "status_code": None}

    # If host is already an IP, accept it
    ip_str: Optional[str] = None
    try:
        ip_obj = ipaddress.ip_address(host)
        ip_str = str(ip_obj)
    except Exception:
        ip_str = None

    # Helper: DNS resolution using dnspython (A then AAAA) with retries
    def resolve_with_dnspython(name: str) -> (Optional[str], Optional[str]):
        resolver = dns.resolver.Resolver()
        last_err = None
        # try A (IPv4) then AAAA (IPv6)
        record_types = ["A", "AAAA"]
        for rtype in record_types:
            for attempt in range(1, max_retries + 1):
                try:
                    answers = resolver.resolve(name, rtype, lifetime=timeout)
                    for r in answers:
                        # return first record
                        return (r.to_text(), None)
                except Exception as e:
                    last_err = e
                    # if it's NXDOMAIN or NoAnswer for this type, break/try next type
                    # but keep retrying on timeouts
                    if isinstance(e, dns.resolver.NXDOMAIN):
                        return (None, f"DNS NXDOMAIN for {name}")
                    if isinstance(e, dns.resolver.NoNameservers):
                        return (None, f"No name servers available for {name}: {e}")
                    if isinstance(e, dns.resolver.NoAnswer):
                        # try next record type
                        break
                    if attempt < max_retries:
                        time.sleep(0.5 * attempt)
                        continue
                    else:
                        # give up on this record type
                        break
        return (None, f"DNS resolution failed: {last_err}")

    # Helper: DNS resolution using socket fallback
    def resolve_with_socket(name: str) -> (Optional[str], Optional[str]):
        last_err = None
        # prefer IPv4 then IPv6
        for family in (socket.AF_INET, socket.AF_INET6):
            for attempt in range(1, max_retries + 1):
                try:
                    infos = socket.getaddrinfo(name, None, family, socket.SOCK_STREAM)
                    if infos:
                        # get first address
                        addr = infos[0][4][0]
                        return (addr, None)
                except socket.gaierror as e:
                    last_err = e
                    # if EAI_NONAME (name or service not known) treat as permanent
                    if e.errno in (socket.EAI_NONAME,):
                        return (None, f"DNS error: {e}")
                    if attempt < max_retries:
                        time.sleep(0.5 * attempt)
                        continue
                    else:
                        break
                except Exception as e:
                    last_err = e
                    if attempt < max_retries:
                        time.sleep(0.5 * attempt)
                        continue
                    else:
                        break
        return (None, f"Socket resolution failed: {last_err}")

    # Resolve if we didn't already get an IP
    if ip_str is None:
        if DNSPY_AVAILABLE:
            ip_str, dns_err = resolve_with_dnspython(host)
            if ip_str is None:
                # if dns_err is a fatal message, return it
                return {"success": False, "ip": None, "data": None, "error": dns_err, "status_code": None}
        else:
            ip_str, dns_err = resolve_with_socket(host)
            if ip_str is None:
                return {"success": False, "ip": None, "data": None, "error": dns_err, "status_code": None}

    # Build ipinfo URL
    base_url = f"https://ipinfo.io/{ip_str}/json"
    if token:
        url = base_url + ("?token=" + token)
    else:
        url = base_url

    # HTTP request with retries
    last_http_err = None
    status_code = None
    content = None
    for attempt in range(1, max_retries + 1):
        try:
            if HTTPX_AVAILABLE:
                # use httpx with a short timeout
                with httpx.Client(timeout=timeout, follow_redirects=True) as client:
                    resp = client.get(url)
                    status_code = resp.status_code
                    if 200 <= status_code < 300:
                        # parse JSON
                        try:
                            content = resp.json()
                            return {"success": True, "ip": ip_str, "data": content, "error": None, "status_code": status_code}
                        except Exception as e:
                            return {"success": False, "ip": ip_str, "data": None, "error": f"Failed to parse JSON from ipinfo: {e}", "status_code": status_code}
                    else:
                        # non-2xx: treat specially for rate limit
                        if status_code == 429:
                            return {"success": False, "ip": ip_str, "data": None, "error": f"ipinfo rate-limited (HTTP {status_code})", "status_code": status_code}
                        # other non-200: read body as text if possible
                        try:
                            text = resp.text
                        except Exception:
                            text = "<no body>"
                        return {"success": False, "ip": ip_str, "data": None, "error": f"ipinfo returned HTTP {status_code}: {text}", "status_code": status_code}
            else:
                # urllib fallback
                req = urllib.request.Request(url, headers={"User-Agent": "python-ipinfo-client/1.0"})
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    status_code = getattr(resp, "status", None)
                    raw = resp.read()
                    # parse JSON
                    try:
                        content = json.loads(raw.decode("utf-8"))
                        return {"success": True, "ip": ip_str, "data": content, "error": None, "status_code": status_code}
                    except Exception as e:
                        return {"success": False, "ip": ip_str, "data": None, "error": f"Failed to parse JSON from ipinfo: {e}", "status_code": status_code}
        except Exception as e:
            last_http_err = e
            # on last attempt, break and report error
            if attempt < max_retries:
                # small backoff
                time.sleep(0.5 * attempt)
                continue
            else:
                break

    # If we reach here, HTTP attempts failed
    err_msg = f"Failed to fetch ipinfo for {ip_str}: {last_http_err}"
    return {"success": False, "ip": ip_str, "data": None, "error": err_msg, "status_code": status_code}

