def task_func(data):
    """
    Authenticate input credentials and return a simple HTTP-like response object.

    Expects:
      data: dict with 'username' (str) and 'password' (str) keys.
            The 'password' value must be a base64-encoded SHA-256 digest.

    Behavior:
      - If username == 'admin' and the decoded SHA-256 digest matches the SHA-256 of b'password',
        returns a 200 response with a JSON success message.
      - For invalid credentials returns a 401 response with "Login failed.".
      - For malformed input returns a 400 response with an appropriate message.

    Returned object has:
      - .status_code (int)
      - .content (bytes)
      - .headers (dict)
    """
    import base64
    import hashlib
    import json

    class SimpleResponse:
        def __init__(self, content: bytes, status_code: int, content_type: str = "text/plain"):
            self.content = content
            self.status_code = status_code
            self.headers = {"Content-Type": content_type}

        def __repr__(self):
            return f"<SimpleResponse {self.status_code} {self.headers.get('Content-Type')}>"

    # Basic validation
    if not isinstance(data, dict):
        return SimpleResponse(b"Bad request: expected a dict", 400)

    username = data.get("username")
    password_b64 = data.get("password")

    if not username or not password_b64:
        return SimpleResponse(b"Bad request: missing username or password", 400)

    # Decode the base64-encoded SHA-256 digest
    try:
        decoded_digest = base64.b64decode(password_b64, validate=True)
    except Exception:
        return SimpleResponse(b"Bad request: invalid base64 encoding for password", 400)

    # Expected digest for demonstration: SHA-256 of b'password'
    expected_digest = hashlib.sha256(b"password").digest()

    if username == "admin" and decoded_digest == expected_digest:
        payload = json.dumps({"message": "Login successful."}).encode("utf-8")
        return SimpleResponse(payload, 200, content_type="application/json")
    else:
        return SimpleResponse(b"Login failed.", 401, content_type="text/plain")

