import base64
import hashlib
import hmac
from typing import Any, Dict

class SimpleResponse:
    """Minimal response object with attributes used in the example."""
    def __init__(self, content: bytes, status_code: int = 200, headers: Dict[str, str] = None):
        self.content = content
        self.status_code = status_code
        self.headers = headers or {}

def task_func(data: Dict[str, Any]) -> SimpleResponse:
    """
    Authenticate provided credentials.

    Expects data to be a dict with keys:
      - 'username': str
      - 'password': base64-encoded SHA-256 digest (string)

    For demonstration, the only valid credentials are:
      username == 'admin' and password == base64.b64encode(sha256(b'password').digest()).decode()

    Returns a SimpleResponse with:
      - status_code 200 and content b'Login successful.' on success
      - status_code 401 and content b'Login failed.' on authentication failure
      - status_code 400 and an explanatory message on bad input
    """
    if not isinstance(data, dict):
        return SimpleResponse(b'Bad request: expected a dictionary.', 400)

    username = data.get('username')
    password_b64 = data.get('password')

    if username is None or password_b64 is None:
        return SimpleResponse(b'Bad request: missing username or password.', 400)

    if not isinstance(password_b64, str):
        return SimpleResponse(b'Bad request: password must be a base64-encoded string.', 400)

    try:
        decoded = base64.b64decode(password_b64, validate=True)
    except (base64.binascii.Error, ValueError):
        return SimpleResponse(b'Bad request: invalid base64 password encoding.', 400)

    # Expected hash is SHA-256 of the literal password 'password'
    expected_hash = hashlib.sha256(b'password').digest()

    # Use constant-time comparison
    if username == 'admin' and hmac.compare_digest(decoded, expected_hash):
        return SimpleResponse(b'Login successful.', 200)
    else:
        return SimpleResponse(b'Login failed.', 401)
