from typing import Any, Iterable, Optional
import math
import numpy as np
import seaborn as sns
import matplotlib.pyplot as plt

def plot_hist_with_custom_normal(
    value_objs: Iterable[Any],
    *,
    value_attr: str = "value",
    bins: int = 30,
    hist_color: str = "C0",
    curve_color: str = "C1",
    ax: Optional[plt.Axes] = None,
) -> plt.Axes:
    """
    Draw a histogram (density) from the numeric values carried by value_objs and overlay a custom
    normal distribution curve computed from the sample mean and standard deviation.
    Returns the matplotlib Axes containing the plot.

    Behavior and assumptions:
    - value_objs may contain plain numbers or objects exposing a numeric attribute:
        - tries (in order): numeric, attribute `value_attr`, attribute 'value', method 'get_value()', or float(obj)
    - If the provided iterable is empty, mean and std are taken as 0.
    - If std == 0 (all values equal or empty), the normal curve is plotted as a vertical dashed line at the mean.

    Parameters:
    - value_objs: iterable of objects (or numbers) carrying the numeric values
    - value_attr: attribute name to try first to extract the numeric value from an object
    - bins: number of histogram bins
    - hist_color: color for the histogram
    - curve_color: color for the normal curve (or vertical line when std == 0)
    - ax: existing matplotlib Axes to plot on; if None a new figure/axes is created

    Returns:
    - matplotlib.axes.Axes with the histogram and the overlaid normal curve
    """

    # Helper to pull numeric value from an item
    def _extract_number(item: Any) -> Optional[float]:
        # direct numeric
        if isinstance(item, (int, float, np.number)):
            return float(item)
        # try configured attribute
        if hasattr(item, value_attr):
            v = getattr(item, value_attr)
            if callable(v):
                try:
                    return float(v())
                except Exception:
                    return None
            try:
                return float(v)
            except Exception:
                return None
        # common alternatives
        if hasattr(item, "value"):
            v = getattr(item, "value")
            if callable(v):
                try:
                    return float(v())
                except Exception:
                    return None
            try:
                return float(v)
            except Exception:
                return None
        if hasattr(item, "get_value"):
            try:
                return float(item.get_value())
            except Exception:
                return None
        # fallback to attempting float conversion
        try:
            return float(item)
        except Exception:
            return None

    # Extract numeric values
    values = []
    for it in value_objs:
        num = _extract_number(it)
        if num is not None and not (isinstance(num, float) and (math.isnan(num) or math.isinf(num))):
            values.append(num)

    # Prepare axes
    if ax is None:
        fig, ax = plt.subplots()

    # Compute mean and std (population std, ddof=0). For empty list, mean=0,std=0 as requested.
    if len(values) == 0:
        mean = 0.0
        std = 0.0
    else:
        arr = np.array(values, dtype=float)
        mean = float(np.mean(arr))
        std = float(np.std(arr, ddof=0))

    # Plot histogram as density
    # If values empty, histplot will produce no bars; set a reasonable x-range around mean.
    sns.histplot(values, bins=bins, stat="density", ax=ax, color=hist_color)

    # Determine x-range for the normal curve
    if len(values) > 0:
        data_min, data_max = min(values), max(values)
        span = data_max - data_min
        if span == 0:
            # all values identical: center around the value
            x_min = mean - 1.0
            x_max = mean + 1.0
        else:
            padding = span * 0.1
            x_min = data_min - padding
            x_max = data_max + padding
    else:
        # empty: choose a small range around 0
        x_min, x_max = mean - 1.0, mean + 1.0

    x = np.linspace(x_min, x_max, 300)

    # Plot normal pdf or vertical line if std == 0
    if std > 0.0:
        coeff = 1.0 / (std * math.sqrt(2 * math.pi))
        pdf = coeff * np.exp(-0.5 * ((x - mean) / std) ** 2)
        ax.plot(x, pdf, color=curve_color, lw=2, label=f"N({mean:.3g}, {std:.3g}^2)")
    else:
        # plot a dashed vertical line at the mean to indicate degenerate distribution
        ax.axvline(mean, color=curve_color, linestyle="--", lw=2, label=f"mean={mean:.3g}, std=0")

    ax.set_xlabel("value")
    ax.set_ylabel("density")
    ax.legend()

    return ax

# Example of a simple ValueObject class (for testing)
if __name__ == "__main__":
    class ValueObject:
        def __init__(self, v):
            self.value = v

    data = [ValueObject(v) for v in [1, 2, 2, 3, 4, 5]]
    ax = plot_hist_with_custom_normal(data)
    plt.show()

def display_system_usage():
    """
    Gather system CPU, memory, and disk usage and display them in a nice table.
    This function will try to use the 'rich' library to render a table if available;
    if not, it will fall back to a simple text table.

    The metrics are retrieved using:
      - psutil (if present) for the most accurate cross-platform results,
      - otherwise platform-specific fallbacks:
        - Linux: /proc/stat and /proc/meminfo
        - Windows: wmic commands
        - macOS/other: best-effort fallbacks (load average for CPU).
    The disk usage uses shutil.disk_usage (cross-platform).
    """
    import os
    import sys
    import time
    import shutil
    import subprocess
    from math import isfinite

    # Try to import optional nicer libraries
    try:
        import psutil
    except Exception:
        psutil = None

    try:
        from rich.console import Console
        from rich.table import Table
        _HAS_RICH = True
        console = Console()
    except Exception:
        _HAS_RICH = False
        console = None

    def get_cpu_percent():
        # Prefer psutil if available
        if psutil:
            try:
                return round(psutil.cpu_percent(interval=0.5), 1)
            except Exception:
                pass

        # Windows fallback: wmic CPU get loadpercentage
        if sys.platform.startswith("win"):
            try:
                out = subprocess.check_output(["wmic", "cpu", "get", "loadpercentage"], stderr=subprocess.DEVNULL, text=True)
                # Output lines, take first numeric token
                for line in out.splitlines():
                    line = line.strip()
                    if line and line.lower() != "loadpercentage":
                        try:
                            v = float(line)
                            return round(v, 1)
                        except Exception:
                            continue
            except Exception:
                pass

        # Linux fallback: parse /proc/stat
        if sys.platform.startswith("linux"):
            def read_cpu():
                with open("/proc/stat", "r") as f:
                    for line in f:
                        if line.startswith("cpu "):
                            parts = line.split()
                            # cpu user nice system idle iowait irq softirq steal ...
                            vals = [float(p) for p in parts[1:]]
                            idle = vals[3]  # idle
                            total = sum(vals)
                            return idle, total
                raise RuntimeError("Could not read /proc/stat")
            try:
                idle1, total1 = read_cpu()
                time.sleep(0.4)
                idle2, total2 = read_cpu()
                idle_delta = idle2 - idle1
                total_delta = total2 - total1
                if total_delta > 0:
                    cpu_percent = (1.0 - idle_delta / total_delta) * 100.0
                    return round(max(0.0, min(cpu_percent, 100.0)), 1)
            except Exception:
                pass

        # macOS / other fallback: use load average / cpu count as approximation
        try:
            load1, _, _ = os.getloadavg()
            cpu_count = os.cpu_count() or 1
            cpu_percent = (load1 / cpu_count) * 100.0
            if isfinite(cpu_percent):
                return round(max(0.0, min(cpu_percent, 100.0)), 1)
        except Exception:
            pass

        return float("nan")

    def get_memory_usage():
        # Returns tuple (used_percent, total_bytes, used_bytes, free_bytes)
        if psutil:
            try:
                vm = psutil.virtual_memory()
                return round(vm.percent, 1), vm.total, vm.used, vm.available
            except Exception:
                pass

        # Windows fallback via wmic
        if sys.platform.startswith("win"):
            try:
                out = subprocess.check_output(["wmic", "OS", "get", "FreePhysicalMemory,TotalVisibleMemorySize", "/Value"],
                                              stderr=subprocess.DEVNULL, text=True)
                free_kb = None
                total_kb = None
                for line in out.splitlines():
                    if not line:
                        continue
                    if line.startswith("FreePhysicalMemory="):
                        free_kb = float(line.split("=", 1)[1])
                    elif line.startswith("TotalVisibleMemorySize="):
                        total_kb = float(line.split("=", 1)[1])
                if total_kb is not None and free_kb is not None:
                    total = total_kb * 1024.0
                    free = free_kb * 1024.0
                    used = max(0.0, total - free)
                    percent = (used / total) * 100.0 if total > 0 else float("nan")
                    return round(percent, 1), int(total), int(used), int(free)
            except Exception:
                pass

        # Linux fallback: parse /proc/meminfo
        if sys.platform.startswith("linux"):
            try:
                meminfo = {}
                with open("/proc/meminfo", "r") as f:
                    for line in f:
                        parts = line.split(":")
                        if len(parts) < 2:
                            continue
                        key = parts[0].strip()
                        val = parts[1].strip().split()[0]
                        meminfo[key] = float(val)  # in KB
                # Prefer MemAvailable if present
                if "MemTotal" in meminfo:
                    total_kb = meminfo.get("MemTotal", 0.0)
                    if "MemAvailable" in meminfo:
                        free_kb = meminfo.get("MemAvailable", 0.0)
                    else:
                        # approximate: MemFree + Buffers + Cached
                        free_kb = meminfo.get("MemFree", 0.0) + meminfo.get("Buffers", 0.0) + meminfo.get("Cached", 0.0)
                    total = total_kb * 1024.0
                    free = free_kb * 1024.0
                    used = max(0.0, total - free)
                    percent = (used / total) * 100.0 if total > 0 else float("nan")
                    return round(percent, 1), int(total), int(used), int(free)
            except Exception:
                pass

        # macOS/other fallback: try vm_stat (macOS) or give NaNs
        if sys.platform.startswith("darwin"):
            try:
                out = subprocess.check_output(["vm_stat"], text=True)
                page_size = 4096
                pages = {}
                for line in out.splitlines():
                    if ":" in line:
                        key, val = line.split(":", 1)
                        key = key.strip().replace(" ", "_")
                        val = val.strip().strip(".").split()[0]
                        pages[key] = int(val)
                free = (pages.get("Pages_free", 0) + pages.get("Pages_inactive", 0)) * page_size
                # total memory via sysctl
                total_out = subprocess.check_output(["sysctl", "-n", "hw.memsize"], text=True)
                total = int(total_out.strip())
                used = max(0, total - free)
                percent = (used / total) * 100.0 if total > 0 else float("nan")
                return round(percent, 1), int(total), int(used), int(free)
            except Exception:
                pass

        return float("nan"), 0, 0, 0

    def get_disk_usage(path="/"):
        try:
            du = shutil.disk_usage(path)
            total, used, free = du.total, du.used, du.free
            percent = (used / total) * 100.0 if total > 0 else float("nan")
            return round(percent, 1), total, used, free
        except Exception:
            return float("nan"), 0, 0, 0

    # Collect metrics
    cpu_pct = get_cpu_percent()
    mem_pct, mem_total, mem_used, mem_free = get_memory_usage()
    disk_pct, disk_total, disk_used, disk_free = get_disk_usage("/")

    # Helper to format bytes
    def fmt_bytes(n):
        if n is None:
            return "N/A"
        n = float(n)
        if n < 0:
            return "N/A"
        for unit in ("B", "KB", "MB", "GB", "TB", "PB"):
            if n < 1024.0 or unit == "PB":
                return f"{n:,.1f} {unit}"
            n /= 1024.0
        return f"{n:,.1f} PB"

    # Display using rich if available
    if _HAS_RICH:
        t = Table(title="System Usage")
        t.add_column("Metric", style="bold")
        t.add_column("Usage")
        t.add_column("Details", justify="right")

        cpu_details = "-"
        if isfinite(cpu_pct):
            cpu_usage = f"{cpu_pct:.1f}%"
        else:
            cpu_usage = "N/A"

        mem_details = f"{fmt_bytes(mem_used)} / {fmt_bytes(mem_total)} (free {fmt_bytes(mem_free)})" if mem_total else "N/A"
        mem_usage = f"{mem_pct:.1f}%" if isfinite(mem_pct) else "N/A"

        disk_details = f"{fmt_bytes(disk_used)} / {fmt_bytes(disk_total)} (free {fmt_bytes(disk_free)})" if disk_total else "N/A"
        disk_usage = f"{disk_pct:.1f}%" if isfinite(disk_pct) else "N/A"

        t.add_row("CPU", cpu_usage, cpu_details)
        t.add_row("Memory", mem_usage, mem_details)
        t.add_row("Disk (root)", disk_usage, disk_details)

        console.print(t)
    else:
        # Simple text table fallback
        rows = [
            ("CPU", f"{cpu_pct:.1f}%" if isfinite(cpu_pct) else "N/A", "-"),
            ("Memory", f"{mem_pct:.1f}%" if isfinite(mem_pct) else "N/A",
             f"{fmt_bytes(mem_used)} / {fmt_bytes(mem_total)} (free {fmt_bytes(mem_free)})" if mem_total else "N/A"),
            ("Disk (root)", f"{disk_pct:.1f}%" if isfinite(disk_pct) else "N/A",
             f"{fmt_bytes(disk_used)} / {fmt_bytes(disk_total)} (free {fmt_bytes(disk_free)})" if disk_total else "N/A"),
        ]
        # Compute column widths
        col1w = max(len(r[0]) for r in rows) + 2
        col2w = max(len(r[1]) for r in rows) + 2
        col3w = max(len(r[2]) for r in rows) + 2

        sep = "+" + "-" * col1w + "+" + "-" * col2w + "+" + "-" * col3w + "+"
        header = f"| {'Metric'.ljust(col1w-2)} | {'Usage'.ljust(col2w-2)} | {'Details'.ljust(col3w-2)} |"
        print(sep)
        print(header)
        print(sep)
        for r in rows:
            print(f"| {r[0].ljust(col1w-2)} | {r[1].ljust(col2w-2)} | {r[2].ljust(col3w-2)} |")
        print(sep)

# Example usage:
if __name__ == "__main__":
    display_system_usage()

def excel_to_csv(excel_path, csv_dest=None, sheet_name=None, sheet_index=0, delimiter=',', encoding='utf-8'):
    """
    Convert an Excel file (.xls or .xlsx) to a CSV file.

    - If csv_dest is None, the CSV will be created next to the Excel file with the same base name and .csv extension.
    - If csv_dest is a directory path, the CSV will be written into that directory with the same base name.
    - If csv_dest is a file path, that exact path will be used.
    - For workbooks with multiple sheets, you can specify sheet_name (preferred) or sheet_index (0-based).
      By default the first sheet (index 0) is used.

    Uses:
      - openpyxl for .xlsx files
      - xlrd for .xls files

    Requirements:
      pip install openpyxl xlrd

    Returns:
      The full path to the written CSV file.

    Raises:
      FileNotFoundError if the Excel file doesn't exist.
      ValueError for unsupported extensions or missing sheet.
      ImportError if required libraries are not installed.
    """
    import os
    import csv

    # Basic validation and destination path resolution
    if not os.path.isfile(excel_path):
        raise FileNotFoundError(f"Excel file not found: {excel_path}")

    base_name = os.path.splitext(os.path.basename(excel_path))[0]
    if csv_dest is None:
        csv_path = os.path.join(os.path.dirname(excel_path), base_name + '.csv')
    elif os.path.isdir(csv_dest):
        csv_path = os.path.join(csv_dest, base_name + '.csv')
    else:
        csv_path = csv_dest

    # Ensure destination directory exists
    os.makedirs(os.path.dirname(os.path.abspath(csv_path)), exist_ok=True)

    ext = os.path.splitext(excel_path)[1].lower()

    def cell_to_str(v):
        # Normalize cell values to strings for CSV writing
        if v is None:
            return ''
        # bytes (possible from some older formats)
        if isinstance(v, (bytes, bytearray)):
            try:
                return v.decode(encoding)
            except Exception:
                return v.decode(errors='replace')
        return str(v)

    # Handle .xlsx with openpyxl
    if ext == '.xlsx':
        try:
            import openpyxl
        except ImportError:
            raise ImportError("openpyxl is required to read .xlsx files. Install with: pip install openpyxl")

        wb = openpyxl.load_workbook(excel_path, read_only=True, data_only=True)
        # pick sheet
        ws = None
        if sheet_name is not None:
            if sheet_name in wb.sheetnames:
                ws = wb[sheet_name]
            else:
                raise ValueError(f"Sheet named '{sheet_name}' not found in workbook")
        else:
            try:
                ws = wb.worksheets[sheet_index]
            except Exception:
                raise ValueError(f"Sheet index {sheet_index} not available (workbook has {len(wb.worksheets)} sheets)")

        with open(csv_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter)
            for row in ws.iter_rows(values_only=True):
                writer.writerow([cell_to_str(c) for c in row])

        wb.close()
        return os.path.abspath(csv_path)

    # Handle .xls with xlrd
    elif ext == '.xls':
        try:
            import xlrd
        except ImportError:
            raise ImportError("xlrd is required to read .xls files. Install with: pip install xlrd")

        book = xlrd.open_workbook(excel_path, on_demand=True)
        # pick sheet
        if sheet_name is not None:
            try:
                sheet = book.sheet_by_name(sheet_name)
            except xlrd.biffh.XLRDError:
                raise ValueError(f"Sheet named '{sheet_name}' not found in workbook")
        else:
            try:
                sheet = book.sheet_by_index(sheet_index)
            except IndexError:
                raise ValueError(f"Sheet index {sheet_index} not available (workbook has {book.nsheets} sheets)")

        with open(csv_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter)
            for r in range(sheet.nrows):
                row = [cell_to_str(sheet.cell_value(r, c)) for c in range(sheet.ncols)]
                writer.writerow(row)

        book.release_resources()
        return os.path.abspath(csv_path)

    else:
        raise ValueError("Unsupported file extension. Only .xls and .xlsx are supported.")

Here's a single self-contained Python function that parses an XML string using the standard library's xml.etree.ElementTree, converts it to a dictionary (attributes prefixed with "@", text stored under "#text"), and writes the result to a JSON file.

```python
import json
import xml.etree.ElementTree as ET
from typing import Any, Dict


def xml_to_json_file(xml_string: str, json_filepath: str, indent: int = 2, encoding: str = "utf-8") -> None:
    """
    Convert an XML string to a dictionary and save it as a JSON file.

    - Attributes are stored with keys prefixed by '@'.
    - Element text is stored under '#text' when the element has children or attributes;
      if an element only contains text, the value is that text (not wrapped).
    - Repeated child tags are grouped into lists.

    Args:
        xml_string: The XML content as a string.
        json_filepath: Path to the JSON file to write.
        indent: Indentation for the JSON output (pass None for compact output).
        encoding: File encoding for writing the JSON file.

    Raises:
        ValueError: If the XML cannot be parsed.
        OSError: If writing to the JSON file fails.
    """
    def _strip_namespace(tag: str) -> str:
        # Remove namespace if present: "{namespace}local" -> "local"
        if tag is None:
            return tag
        if "}" in tag:
            return tag.split("}", 1)[1]
        return tag

    def _element_to_dict(elem: ET.Element) -> Dict[str, Any]:
        tag = _strip_namespace(elem.tag)
        data: Dict[str, Any] = {}

        # Attributes
        for k, v in elem.attrib.items():
            data[f"@{_strip_namespace(k)}"] = v

        # Children
        children = list(elem)
        if children:
            for child in children:
                child_dict = _element_to_dict(child)  # returns {child_tag: child_value}
                for child_tag, child_val in child_dict.items():
                    if child_tag in data:
                        # Convert to list if necessary
                        if isinstance(data[child_tag], list):
                            data[child_tag].append(child_val)
                        else:
                            data[child_tag] = [data[child_tag], child_val]
                    else:
                        data[child_tag] = child_val

        # Text
        text = (elem.text or "").strip()
        if text:
            if children or elem.attrib:
                data["#text"] = text
            else:
                # Element with only text (no children/attributes) -> return text directly
                return {tag: text}

        return {tag: data}

    # Parse XML
    try:
        root = ET.fromstring(xml_string)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse XML: {e}") from e

    # Convert to dict
    result_dict = _element_to_dict(root)

    # Write JSON
    with open(json_filepath, "w", encoding=encoding) as f:
        json.dump(result_dict, f, ensure_ascii=False, indent=indent)
```

Example usage:
- xml_to_json_file("<root><item id='1'>Hello</item><item id='2'>World</item></root>", "out.json")

This creates out.json with a dictionary structure that preserves attributes and grouping of repeated elements.

Here's a self-contained Python function that uses Plotly Express (an alternative to matplotlib) to plot a bar chart of monthly data for a single year. The function accepts several input types (list of 12 values, dict mapping months to values, list of (month, value) pairs, or a DataFrame-like object with 'month' and 'value' columns). It orders months Jan–Dec, fills missing months with a specified value, and can show the plot or save it to a file.

Paste this into a .py file or a notebook cell and run. If plotly is not installed, install it with pip install plotly.

```
def plot_monthly_bars(
    data,
    year=None,
    month_col='month',
    value_col='value',
    title=None,
    fill_missing=0,
    show=True,
    output=None
):
    """
    Plot a bar chart of monthly values for a single year using Plotly Express.

    Parameters:
    - data: one of
        * list/tuple of 12 numeric values (assumed Jan..Dec order)
        * dict mapping month -> value (month can be int 1-12 or name like 'Jan'/'January')
        * list of (month, value) pairs
        * DataFrame-like with attributes .columns and indexable rows; uses month_col and value_col
    - year: optional int or str to include in the title
    - month_col: column name to use if `data` is DataFrame-like (default 'month')
    - value_col: column name for values (default 'value')
    - title: optional title string (if None and year provided, will use "Monthly values — <year>")
    - fill_missing: numeric value used for months not present in `data` (default 0)
    - show: if True, display the interactive plot (default True)
    - output: optional filename to save the plot. If ends with '.html' the interactive chart is saved;
              if it ends with an image extension ('.png', '.jpg', '.jpeg', '.svg', etc.) Plotly's
              image engine is used (may require kaleido: pip install -U kaleido)

    Returns:
    - the Plotly figure object
    """
    # Imports
    try:
        import plotly.express as px
    except Exception as e:
        raise ImportError("plotly is required for this function. Install with: pip install plotly") from e

    # canonical 3-letter month names for x-axis
    month_names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                   'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

    # helper: convert a month key (int or string) to 0-based index
    def month_to_index(m):
