        if abbr in lookup:
            return lookup[abbr]
        # try full names
        full_lookup = {name.lower(): i for i, name in enumerate(['January','February','March','April','May','June',
                                                                  'July','August','September','October','November','December'])}
        if s in full_lookup:
            return full_lookup[s]
        raise ValueError(f"Unrecognized month label: {m!r}")

    # Initialize values list for Jan..Dec
    values = [fill_missing] * 12
    provided = [False] * 12  # track which months provided

    # Helper to set month value
    def set_month_value(month_key, val):
        idx = month_to_index(month_key)
        if idx is None:
            return
        values[idx] = val
        provided[idx] = True

    # Detect input types
    # DataFrame-like: has 'columns' and is indexable by rows
    if hasattr(data, 'columns') and hasattr(data, '__getitem__'):
        # try to extract rows
