                break
            # detect pandas DataFrame specifically
            try:
                import pandas as _pd
                if isinstance(data, _pd.DataFrame):
                    for _, row in data.iterrows():
                        set_month_value(row[month_col], row[value_col])
                else:
                    # generic: try attribute access
                    for row in data:
                        # if row is a dict-like
                        if isinstance(row, dict):
                            set_month_value(row.get(month_col), row.get(value_col))
                        else:
                            # try indexing by column names
                            try:
                                set_month_value(row[month_col], row[value_col])
                            except Exception:
                                # fallback: try tuple (month, value)
                                if isinstance(row, (list, tuple)) and len(row) >= 2:
                                    set_month_value(row[0], row[1])
                                else:
                                    raise
            except Exception:
                # fallback generic approach: iterate rows as sequence of (month, value)
                for row in data:
                    if isinstance(row, (list, tuple)) and len(row) >= 2:
                        set_month_value(row[0], row[1])
                    elif isinstance(row, dict):
                        set_month_value(row.get(month_col), row.get(value_col))
                    else:
                        raise ValueError("Couldn't interpret the DataFrame-like input. Provide a DataFrame, dict, mapping, or list of pairs.")
        except Exception:
            # fall back to other handlers below
            pass

    # If data is a dict-like mapping
    if isinstance(data, dict):
        for k, v in data.items():
            set_month_value(k, v)
    # If data is list/tuple
    elif isinstance(data, (list, tuple)):
        # if length == 12 and elements are scalars, assume Jan..Dec order
        if len(data) == 12 and all(not (isinstance(x, (list, tuple, dict))) for x in data):
            values = list(data)
            provided = [True] * 12
        else:
            # assume list of (month, value) pairs or list of dicts
            for item in data:
                if isinstance(item, dict):
                    set_month_value(item.get(month_col), item.get(value_col))
                elif isinstance(item, (list, tuple)) and len(item) >= 2:
                    set_month_value(item[0], item[1])
                else:
                    raise ValueError("List input must be either 12 scalar values (Jan..Dec) or a list of (month, value) pairs or dicts.")
    # If data was not dict/list/tuple and not handled, try single mapping-like object
    else:
        # try mapping protocol
        try:
            for k in data:
                set_month_value(k, data[k])
        except Exception:
            raise ValueError("Unsupported data type for 'data' parameter.")

    # Compose title
    if title is None:
        title = f"Monthly values — {year}" if year is not None else "Monthly values"

    # Build Plotly figure
    fig = px.bar(x=month_names, y=values, labels={'x': 'Month', 'y': 'Value'}, title=title)
    # Ensure months are in the correct order and show hover details
    fig.update_layout(xaxis=dict(tickmode='array', tickvals=month_names, ticktext=month_names),
