import unicodedata
from typing import Any, Dict, Optional
import httpx


def fetch_github_user_ascii(username: str, token: Optional[str] = None, timeout: float = 10.0) -> Dict[str, Any]:
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary with normalized keys and values.

    Parameters:
    - username: GitHub username to look up.
    - token: Optional GitHub API token (string). If provided, used for authenticated requests.
    - timeout: Request timeout in seconds.

    Returns:
    - A dict containing the normalized JSON response from the GitHub API.

    Raises:
    - httpx.HTTPStatusError on non-2xx responses.
    - httpx.RequestError for network-related errors.
    - ValueError if `username` is empty.
    """
    if not username or not isinstance(username, str):
        raise ValueError("`username` must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "httpx-github-client/1.0",
    }
    if token:
        # Use token for higher rate limits; GitHub accepts "token <token>" or "Bearer <token>"
        headers["Authorization"] = f"token {token}"

    with httpx.Client(timeout=timeout, headers=headers) as client:
        response = client.get(url)
        response.raise_for_status()
        data = response.json()

    def _normalize_string(s: str) -> str:
        # Decompose Unicode and drop non-ASCII bytes
        return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")

    def _normalize(obj: Any) -> Any:
        # Recursively normalize strings in dicts, lists, and tuples.
        if isinstance(obj, dict):
            # Normalize keys and values
            normalized = {}
            for k, v in obj.items():
                key = _normalize_string(k) if isinstance(k, str) else k
                normalized[key] = _normalize(v)
            return normalized
        elif isinstance(obj, list):
            return [_normalize(item) for item in obj]
        elif isinstance(obj, tuple):
            # return as list for simplicity; could convert back to tuple if desired
            return [_normalize(item) for item in obj]
        elif isinstance(obj, str):
            return _normalize_string(obj)
        elif isinstance(obj, (bytes, bytearray)):
            # attempt to decode then normalize
            try:
                s = obj.decode("utf-8", errors="replace")
            except Exception:
                s = str(obj)
            return _normalize_string(s)
        else:
            # numbers, booleans, None remain unchanged
            return obj

    return _normalize(data)


if __name__ == "__main__":
    # Quick demo (no token). Replace "octocat" with any GitHub username.
    try:
        result = fetch_github_user_ascii("octocat")
        # Print a few fields for demonstration
        print("login:", result.get("login"))
        print("name:", result.get("name"))
        print("bio:", result.get("bio"))
        print("location:", result.get("location"))
    except Exception as e:
        print("Error fetching user:", e)
