def fetch_github_user_ascii(username: str) -> dict:
    """
    Fetch GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    Uses httpx for HTTP requests and unicodedata for Unicode normalization.

    Raises:
      - ImportError if httpx is not installed.
      - ValueError if username is empty or user not found (404).
      - RuntimeError for network or JSON decoding errors or unexpected HTTP errors.
    """
    import unicodedata

    try:
        import httpx
    except ImportError as e:
        raise ImportError("httpx is required. Install with: pip install httpx") from e

    if not isinstance(username, str) or not username.strip():
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {
        "User-Agent": "fetch-github-user-ascii/1.0",
        "Accept": "application/vnd.github.v3+json",
    }

    try:
        resp = httpx.get(url, headers=headers, timeout=10.0)
    except httpx.RequestError as e:
        raise RuntimeError(f"Network error while requesting GitHub API: {e}") from e

    if resp.status_code == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")
    if resp.status_code >= 400:
        raise RuntimeError(f"GitHub API returned status {resp.status_code}: {resp.text}")

    try:
        data = resp.json()
    except ValueError as e:
        raise RuntimeError("Failed to decode JSON from GitHub API") from e

    def normalize(obj):
        # Normalize strings to ASCII; recurse into lists and dicts.
        if isinstance(obj, str):
            # Use NFKD to decompose characters, then drop non-ASCII.
            return unicodedata.normalize("NFKD", obj).encode("ascii", "ignore").decode("ascii")
        if isinstance(obj, dict):
            new = {}
            for k, v in obj.items():
                nk = normalize(k) if isinstance(k, str) else k
                # If normalization causes duplicate keys, later ones will overwrite earlier.
                new[nk] = normalize(v)
            return new
        if isinstance(obj, list):
            return [normalize(i) for i in obj]
        # Numbers, booleans, None, etc. are returned unchanged.
        return obj

    return normalize(data)
