def word_length_counts(data: dict, letter: str, case_sensitive: bool = False) -> dict:
    """
    Convert `data` (a dict-of-lists) to a DataFrame, filter rows whose 'Word' values
    begin with `letter`, compute the lengths of those words, and return a dict
    mapping word length -> count.

    This implementation uses the Polars library if available; if Polars is not
    installed it falls back to a pure-Python implementation.

    Parameters:
    - data: dict of lists containing at least the key 'Word' (e.g. {'Word': [...], ...})
    - letter: single-character (or string) to match at the start of each word
    - case_sensitive: if False (default) matching is case-insensitive

    Returns:
    - dict where keys are word lengths (int) and values are counts (int)
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dict of lists")
    if 'Word' not in data:
        raise ValueError("data must contain a 'Word' key")
    if not isinstance(letter, str) or len(letter) == 0:
        raise ValueError("letter must be a non-empty string")

    # Try using polars (an alternative to pandas); if not available, fallback to plain Python
    try:
        import polars as pl

        df = pl.DataFrame(data)

        # prepare matching expression
        if case_sensitive:
            starts_expr = pl.col("Word").str.starts_with(letter)
        else:
            starts_expr = pl.col("Word").str.to_lowercase().str.starts_with(letter.lower())

        # filter, compute lengths, group and count
        result_df = (
            df.filter(starts_expr)
              .with_columns(pl.col("Word").str.lengths().alias("length"))
              .groupby("length")
              .agg(pl.count().alias("count"))
              .sort("length")
        )

        # convert to plain dict {length: count}
        return {int(r["length"]): int(r["count"]) for r in result_df.to_dicts()}

    except Exception:
        # Fallback: pure-Python implementation
        from collections import Counter

        words = data.get("Word", [])
        if not isinstance(words, (list, tuple)):
            raise TypeError("data['Word'] must be a list or tuple of strings")

        if case_sensitive:
            filtered = [w for w in words if isinstance(w, str) and w.startswith(letter)]
        else:
            L = letter.lower()
            filtered = [w for w in words if isinstance(w, str) and w.lower().startswith(L)]

        lengths = [len(w) for w in filtered]
        counter = Counter(lengths)
        # return sorted by length (optional)
        return dict(sorted((int(k), int(v)) for k, v in counter.items()))


