def median_nested(L):
    """
    Return the median of all numeric elements in a nested list-like structure L.
    Handles lists and tuples nested to any depth. Raises ValueError if no numeric
    elements are found. Uses the standard 'statistics' module to compute the median.
    """
    import numbers
    import statistics

    def _flatten(obj):
        # Recursively yield numeric items from nested lists/tuples
        if isinstance(obj, (list, tuple)):
            for item in obj:
                yield from _flatten(item)
        else:
            if isinstance(obj, numbers.Number):
                yield obj
            else:
                # Skip or raise depending on desired behavior; here we skip non-numeric
                return

    values = list(_flatten(L))
    if not values:
        raise ValueError("No numeric elements found to compute median.")
    return statistics.median(values)

# Example:
