def median_nested(L):
    """
    Compute the median of all numeric elements contained in a nested list L,
    using NumPy as an alternative library.
    Returns a float median. Raises ValueError if there are no numeric elements.
    """
    import numpy as np

    def _flatten(x):
        for item in x:
            # treat lists and tuples as containers to recurse into;
            # avoid treating strings as iterables of characters
            if isinstance(item, (list, tuple)):
                yield from _flatten(item)
            else:
                yield item

    flat = list(_flatten(L))
    if not flat:
        raise ValueError("median undefined for empty input")

    arr = np.array(flat, dtype=float)  # convert to numeric array
    return float(np.median(arr))

