def iqr_nested(L):
    """
    Compute the interquartile range (IQR = Q3 - Q1) of all numeric elements
    in a nested list/tuple structure L. Uses the standard-library
    statistics.quantiles when available; falls back to linear interpolation
    percentile if needed.

    Returns a float. Raises ValueError if no numeric values are found.
    """
    from statistics import quantiles
    import numbers

    def _flatten(x):
        # Recursively flatten only lists and tuples (keeps other iterables like str out)
        if isinstance(x, (list, tuple)):
            for el in x:
                yield from _flatten(el)
        else:
            yield x

    # Collect numeric values (exclude complex numbers)
    vals = [float(v) for v in _flatten(L) if isinstance(v, numbers.Number) and not isinstance(v, complex)]

    if not vals:
        raise ValueError("No numeric values found in input")

    # Try using statistics.quantiles (returns three cut points for n=4)
    try:
        q1, _, q3 = quantiles(vals, n=4, method='inclusive')
        return float(q3 - q1)
    except Exception:
        # Fallback: compute percentiles by linear interpolation (numpy-like)
        s = sorted(vals)
        def _percentile(sorted_vals, p):
            n = len(sorted_vals)
            if n == 1:
                return sorted_vals[0]
            pos = p * (n - 1)
            lo = int(pos)
            hi = min(lo + 1, n - 1)
            frac = pos - lo
            return sorted_vals[lo] * (1 - frac) + sorted_vals[hi] * frac

        return float(_percentile(s, 0.75) - _percentile(s, 0.25))

