    most_common_values = {}

    try:
        with open(file_path, mode='r', newline='', encoding='utf-8') as csvfile:
            reader = csv.DictReader(csvfile)
            if not reader.fieldnames:
                return {}

            # Initialize counters for each column
            column_counters = {field: Counter() for field in reader.fieldnames}

            # Count occurrences of each value in each column
            for row in reader:
                for field in reader.fieldnames:
                    column_counters[field][row[field]] += 1

            # Determine the most common value for each column
            for field, counter in column_counters.items():
                most_common = counter.most_common()
                if most_common:
                    # Sort by count descending, then alphabetically
                    most_common_values[field] = sorted(most_common, key=lambda x: (-x[1], x[0]))[0][0]

    except FileNotFoundError:
        print(f"File not found: {file_path}")
    except Exception as e:
        print(f"An error occurred: {e}")

    return most_common_values

