import numbers
from typing import Any, List, Union, Iterable
import plotly.graph_objects as go

def extract_and_visualize(json_data: Any,
                          path: Union[str, Iterable[Union[str, int]]],
                          kind: str = 'line',
                          title: str = None,
                          show: bool = True):
    """
    Extract numeric values from json_data following the given path and visualize them using Plotly.

    Parameters:
    - json_data: nested structure of dicts/lists (parsed JSON).
    - path: either a list/tuple of keys/indexes or a dot-separated string.
        Tokens can be:
          - dict key names (strings)
          - integer indexes for lists (e.g. "2" or 2)
          - '*' to mean "all entries at this level" (for lists or dict values)
    - kind: one of 'line', 'bar', 'hist' (default 'line')
    - title: optional plot title
    - show: if True, call fig.show(); function will still return the figure and extracted values.

    Returns:
    - (fig, values) tuple: Plotly Figure and the list of extracted numeric values.

    Raises:
    - ValueError if no numeric values are found or invalid kind is supplied.
    """
    # Helper: parse path into tokens
    def _parse_path(p):
        if isinstance(p, str):
            tokens = p.split('.')
            out = []
            for t in tokens:
                if t == '*':
                    out.append('*')
                else:
                    # try convert to int index, else keep string
                    try:
                        out.append(int(t))
                    except Exception:
                        out.append(t)
            return out
        elif isinstance(p, Iterable):
            # normalize items to int if possible, otherwise keep
            out = []
            for t in p:
                if t == '*':
                    out.append('*')
                elif isinstance(t, int):
                    out.append(t)
                else:
                    try:
                        out.append(int(t))
                    except Exception:
                        out.append(t)
            return out
        else:
            return [p]

    # Helper: collect numeric leaves recursively
    def _collect_numbers(item, out_list):
        if isinstance(item, dict):
            for v in item.values():
                _collect_numbers(v, out_list)
        elif isinstance(item, list) or isinstance(item, tuple):
            for v in item:
                _collect_numbers(v, out_list)
        elif isinstance(item, numbers.Number) and not isinstance(item, bool):
            # exclude booleans
            out_list.append(item)
        # else: ignore non-numeric leaves

    # Main traversal: follow tokens; '*' means iterate all children at that level
    def _traverse(obj, tokens, collector):
        if not tokens:
            # reached target location: collect numbers under this object
            _collect_numbers(obj, collector)
            return
        tok, *rest = tokens
        if tok == '*':
            if isinstance(obj, dict):
                for v in obj.values():
                    _traverse(v, rest, collector)
            elif isinstance(obj, list) or isinstance(obj, tuple):
                for v in obj:
                    _traverse(v, rest, collector)
            else:
                # nothing to iterate; do nothing
                return
        elif isinstance(tok, int):
            if isinstance(obj, (list, tuple)) and 0 <= tok < len(obj):
                _traverse(obj[tok], rest, collector)
            else:
                return
        else:  # string key
            if isinstance(obj, dict) and tok in obj:
                _traverse(obj[tok], rest, collector)
            else:
                return

    tokens = _parse_path(path)
    values = []
    _traverse(json_data, tokens, values)

    if not values:
        raise ValueError(f"No numeric values found at path {path!r}")

    # Prepare plot
    kind = kind.lower()
    if kind not in ('line', 'bar', 'hist'):
        raise ValueError("kind must be one of 'line', 'bar', 'hist'")

    if kind == 'hist':
        fig = go.Figure(data=go.Histogram(x=values))
        fig.update_layout(title=title or f"Histogram of values ({len(values)} samples)",
                          xaxis_title="Value",
                          yaxis_title="Count")
    else:
        x = list(range(len(values)))
        if kind == 'line':
            fig = go.Figure(data=go.Scatter(x=x, y=values, mode='lines+markers'))
            fig.update_layout(title=title or f"Line plot ({len(values)} points)",
                              xaxis_title="Index",
                              yaxis_title="Value")
        else:  # bar
            fig = go.Figure(data=go.Bar(x=x, y=values))
            fig.update_layout(title=title or f"Bar chart ({len(values)} bars)",
                              xaxis_title="Index",
                              yaxis_title="Value")

    if show:
        fig.show()
    return fig, values

# Example usage:
