from typing import Any, List, Sequence, Tuple, Union
import numbers
import math

import plotly.express as px
import plotly.graph_objects as go

def extract_and_visualize(
    json_obj: Any,
    key_path: Union[str, Sequence[Union[str, int]]],
    plot_type: str = "line",
    title: str = None,
    show: bool = True,
    save_path: str = None
) -> Tuple[List[float], go.Figure]:
    """
    Extract numerical values from a nested JSON-like structure following a specified path
    of keys, then visualize the extracted numbers using Plotly.

    Parameters
    - json_obj: The JSON-like object (nested dicts/lists) to search.
    - key_path: Sequence of keys to follow (e.g. ["data", "values"]) or dot-separated string
                ("data.values"). Keys may be strings for dict access or integers for list indices.
                If during traversal a list is encountered, the traversal will try the same key
                for every element of that list (useful for arrays of objects).
    - plot_type: One of "line", "hist", "box", "scatter". Determines visualization style.
    - title: Optional title for the plot.
    - show: If True, call fig.show() to display the figure (in notebooks or supported envs).
    - save_path: If provided, save the figure to this path (e.g., "out.html" or "out.png").

    Returns
    - Tuple of (values, fig) where values is the list of extracted floats/ints and fig is the Plotly figure.
    """

    # Normalize key_path to a list
    if isinstance(key_path, str):
        keys = [k for k in key_path.split(".") if k != ""]
        # attempt to convert numeric-looking keys to ints
        def _maybe_int(k):
            try:
                return int(k)
            except Exception:
                return k
        keys = [_maybe_int(k) for k in keys]
    else:
        keys = list(key_path)

    values: List[float] = []

    def _is_number(x: Any) -> bool:
        return isinstance(x, numbers.Number) and not isinstance(x, bool) and not (isinstance(x, float) and math.isnan(x))

    def _traverse(obj: Any, remaining_keys: List[Union[str, int]]):
        if obj is None:
            return
        if not remaining_keys:
            # collect numeric leaves; if obj is a list/dict, recurse into elements/values
            if _is_number(obj):
                values.append(float(obj))
                return
            if isinstance(obj, list):
                for el in obj:
                    _traverse(el, [])
                return
            if isinstance(obj, dict):
                for v in obj.values():
                    _traverse(v, [])
                return
            # otherwise nothing to extract
            return

        key = remaining_keys[0]
        rest = remaining_keys[1:]

        # If current object is a list, try the same key on each element
        if isinstance(obj, list):
            for el in obj:
                _traverse(el, remaining_keys)
            return

        # If current object is dict-like and key is str, access by key
        if isinstance(obj, dict) and isinstance(key, str):
            if key in obj:
                _traverse(obj[key], rest)
            # else: missing key -> skip silently
            return

        # If current object is list-like and key is int, try index access
        if isinstance(obj, list) and isinstance(key, int):
            if 0 <= key < len(obj):
                _traverse(obj[key], rest)
            return

        # If current object is dict-like and key is int (e.g., numeric-string keys converted),
        # try to access using str(key) as fallback
        if isinstance(obj, dict) and isinstance(key, int):
            str_key = str(key)
            if str_key in obj:
                _traverse(obj[str_key], rest)
            return

        # If key is int and obj is a dict with numeric keys as ints (rare), try direct get
        if isinstance(obj, dict) and key in obj:
            _traverse(obj[key], rest)
            return

        # Not traversable with the given key -> skip
        return

    _traverse(json_obj, keys)

    # Visualization using Plotly
    fig = None
    if not values:
        # create an empty figure with message
        fig = go.Figure()
        fig.add_annotation(text="No numeric values found for the specified path.", showarrow=False)
    else:
        if plot_type == "line":
            fig = px.line(y=values, markers=True, title=title or f"Line plot of extracted values ({len(values)} points)")
            fig.update_xaxes(title="Index")
            fig.update_yaxes(title="Value")
        elif plot_type == "scatter":
            fig = px.scatter(x=list(range(len(values))), y=values, title=title or "Scatter plot of extracted values")
            fig.update_xaxes(title="Index")
            fig.update_yaxes(title="Value")
        elif plot_type == "hist":
            fig = px.histogram(values, nbins=min(50, max(5, len(values)//2)), title=title or "Histogram of extracted values")
            fig.update_xaxes(title="Value")
            fig.update_yaxes(title="Count")
        elif plot_type == "box":
            fig = px.box(values, points="all", title=title or "Box plot of extracted values")
            fig.update_xaxes(title="")
            fig.update_yaxes(title="Value")
        else:
            # fallback to simple scatter
            fig = px.scatter(x=list(range(len(values))), y=values, title=title or "Extracted values")
            fig.update_xaxes(title="Index")
            fig.update_yaxes(title="Value")

    if save_path:
        # let plotly infer file format by extension; for some formats (png/svg), kaleido package may be required.
        try:
            if save_path.lower().endswith(".html"):
                fig.write_html(save_path)
            else:
                fig.write_image(save_path)
        except Exception as e:
            # If saving fails, include a note in the figure
            fig.add_annotation(text=f"Saving failed: {e}", showarrow=False, yref="paper", y=0)

    if show:
        fig.show()

    return values, fig


# Example usage:
if __name__ == "__main__":
    sample = {
        "measurements": [
            {"time": "2021-01-01", "value": 10},
            {"time": "2021-01-02", "value": 12.5},
