    try:
        import easyocr
    except Exception as e:
        raise ImportError("easyocr is required for OCR. Install with: pip install easyocr") from e

    try:
        import ftfy
        _have_ftfy = True
    except Exception:
        _have_ftfy = False

    def _clean_text(s):
