    # Convert to RGB (easyocr accepts numpy arrays)
    try:
        img_rgb = img.convert('RGB')
    except Exception:
        img_rgb = img

    # Step 2: OCR
    reader = easyocr.Reader(list(langs) if not isinstance(langs, str) else [langs], gpu=use_gpu)
    try:
        ocr_result = reader.readtext(np.asarray(img_rgb), detail=0)  # list of strings
    except Exception as e:
        # If OCR fails entirely, skip to fallback
        ocr_result = []

    text_from_ocr = ""
