    text_from_ocr = _clean_text(text_from_ocr)

    if text_from_ocr:
        return text_from_ocr, 'ocr'

    # Fallback: try extracting image comments/EXIF metadata
    if try_image_comment:
        comment = _extract_comment_from_image(img)
        if comment:
            if isinstance(comment, bytes):
                # detect encoding
                guess = chardet.detect(comment)
                enc = guess.get('encoding') or target_encoding
