    Return the total number of elapsed seconds from `start` until now, including leap seconds.

    Parameters
    - start: a datetime.datetime (naive = interpreted as UTC, or timezone-aware) or an ISO-8601 string.

    Returns
    - float: elapsed seconds (can be negative if `start` is in the future).

    Notes
    - This function uses astropy.time to account for leap seconds by converting times to the TAI scale.
    - Requires astropy to be installed: pip install astropy
    """
    import datetime as _dt
    try:
        from astropy.time import Time
    except ImportError as e:
        raise ImportError("astropy is required for leap-second-aware calculations. Install via 'pip install astropy'.") from e

    # Normalize input to a timezone-aware datetime in UTC
    if isinstance(start, str):
        # Try to parse via datetime.fromisoformat first (broad ISO support)
        try:
            dt0 = _dt.datetime.fromisoformat(start)
        except Exception:
            # Fall back to astropy parsing (accepts many ISO forms)
            try:
                t0 = Time(start, scale='utc')
            except Exception:
                raise ValueError("String `start` must be ISO-8601 date/time. Example: '2020-01-01T12:34:56' or '2020-01-01'.")
            t_now = Time.now()
            # Compute using TAI to include leap seconds
            return float((t_now.tai - t0.tai).to('s').value)
    elif isinstance(start, _dt.datetime):
        dt0 = start
    else:
        raise TypeError("start must be a datetime.datetime or an ISO-8601 string")

    # Ensure dt0 is timezone-aware and in UTC
    if dt0.tzinfo is None:
        dt0 = dt0.replace(tzinfo=_dt.timezone.utc)
    else:
        dt0 = dt0.astimezone(_dt.timezone.utc)

    # Create astropy Time objects and compute difference in TAI (includes leap seconds)
    t0 = Time(dt0, scale='utc')
    t_now = Time.now()
    seconds = (t_now.tai - t0.tai).to('s').value
    return float(seconds)

import httpx
from typing import Optional, Dict, Any
from datetime import datetime
import time

def fetch_github_repo_info(
    api_url: str,
    token: Optional[str] = None,
    issue_threshold: int = 100,
    timeout: float = 10.0,
) -> Optional[Dict[str, Any]]:
    """
    Fetches and returns repository information from a GitHub API repository URL.
    - api_url: full GitHub API repo URL, e.g. "https://api.github.com/repos/owner/repo"
    - token: optional GitHub token to increase rate limits (use "token <PAT>" or a raw PAT; function will prepend "token " if needed)
    - issue_threshold: if open issues exceed this number, a warning is printed
    - timeout: request timeout in seconds

    Returns the parsed JSON as a dict on success, or None on failure.
    """
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "httpx-github-client/1.0",
    }
    if token:
        # Accept either a raw token or a token string starting with "token " or "Bearer "
        if not (token.startswith("token ") or token.startswith("Bearer ")):
            headers["Authorization"] = f"token {token}"
        else:
            headers["Authorization"] = token

    try:
        with httpx.Client(timeout=timeout, headers=headers) as client:
            resp = client.get(api_url)
    except httpx.RequestError as e:
        print(f"Request error while contacting GitHub API: {e}")
        return None

    # Handle HTTP-level errors
    status = resp.status_code
    if status == 200:
        try:
            data = resp.json()
        except ValueError:
            print("Received non-JSON response from GitHub API.")
            return None

        # Check for open issues count in response and warn if large
        open_issues = None
        if isinstance(data, dict):
            # GitHub main repo API uses 'open_issues_count'
            open_issues = data.get("open_issues_count")
            # Some endpoints or augmented payloads might use other keys
            if open_issues is None:
                open_issues = data.get("open_issues")
        if isinstance(open_issues, int) and open_issues > issue_threshold:
            print(
                f"Warning: repository reports {open_issues} open issues, "
                f"which exceeds the threshold of {issue_threshold}."
            )

        return data

    # Rate limit handling
    if status == 403:
        remaining = resp.headers.get("X-RateLimit-Remaining")
        reset = resp.headers.get("X-RateLimit-Reset")
        retry_after = resp.headers.get("Retry-After")

        body_text = ""
        try:
            body_json = resp.json()
            # GitHub often returns a message field explaining the reason
            body_text = body_json.get("message", "")
        except ValueError:
            body_text = resp.text[:200]

        if remaining == "0" or "rate limit exceeded" in body_text.lower():
            reset_time = None
            try:
                if reset:
                    reset_time = datetime.utcfromtimestamp(int(reset)).strftime("%Y-%m-%d %H:%M:%S UTC")
            except Exception:
                reset_time = None

            if reset_time:
                print(
                    f"GitHub API rate limit exceeded. Remaining=0. Rate limit will reset at {reset_time}."
                )
            elif retry_after:
                print(
                    f"GitHub API rate limit or abuse detection triggered. Retry after {retry_after} seconds."
                )
            else:
                print("GitHub API rate limit exceeded or access forbidden: " + (body_text or f"HTTP {status}"))
            return None
        else:
            # Other 403 reasons (abuse detection, blocked, etc.)
            print("Access forbidden (403): " + (body_text or resp.text[:200]))
            return None

    # Other client/server errors
    if 400 <= status < 600:
        snippet = ""
        try:
            snippet = resp.json().get("message", "")
        except Exception:
            snippet = resp.text[:200]
        print(f"HTTP error {status} when fetching repository: {snippet}")
        return None

    # Unhandled non-200 but non-error status (rare)
    print(f"Unexpected HTTP status {status}. Response: {resp.text[:200]}")
    return None

