Here's a single self-contained Python function that parses string-formatted weights to floats (with basic support for "kg" and "lb"/"lbs" detection) and plots a scatter plot of weight vs. height using Plotly (an alternative to matplotlib). The function uses only standard library + numpy + plotly, and will default to a built-in dataset when no input is provided.

```python
def plot_weights_vs_height(data=None, convert_lbs_to_kg=True, show=True):
    """
    Convert string-formatted weights to floats and plot weight vs height using Plotly.

    Parameters:
    - data: dict with two keys:
        - 'Weight_String': list of weights in string form (e.g., "70kg", "154 lbs", "65.5")
        - 'Height': list of numeric heights (same length as weights)
      If None is provided, a small default dataset will be used.
    - convert_lbs_to_kg: bool, if True any weight strings containing 'lb' or 'lbs' will be converted to kg.
      Strings containing 'kg' are assumed to be kilograms. Strings without unit are treated as numeric (no conversion).
    - show: bool, if True the Plotly figure will be displayed with fig.show().

    Returns:
    - dict with keys:
        - 'weights_kg': list of floats (weights in kg if conversion applied or as parsed)
        - 'heights': list of heights (as provided)
        - 'fig': the Plotly figure object
    """
    import re
    import math
    import numpy as np
    import plotly.express as px

    # default dataset
    if data is None:
        data = {
            'Weight_String': ['70kg', '154 lbs', '60.5', '82 kg', '140lb', '95.2', '68.0kg', '200 lbs'],
            'Height': [175, 168, 160, 182, 170, 178, 165, 190]
        }

    if not isinstance(data, dict):
        raise TypeError("data must be a dict with keys 'Weight_String' and 'Height'")

    if 'Weight_String' not in data or 'Height' not in data:
        raise KeyError("data dict must contain 'Weight_String' and 'Height' keys")

    weights_raw = data['Weight_String']
    heights = data['Height']

    if len(weights_raw) != len(heights):
        raise ValueError("Length of 'Weight_String' must match length of 'Height'")

    def parse_weight(s):
        """
        Parse a weight string to a float. Returns (float or np.nan, unit_detected)
        unit_detected is one of: 'kg', 'lb', None
        """
        if s is None:
            return (np.nan, None)
        # If already numeric
        if isinstance(s, (int, float, np.floating, np.integer)):
            return (float(s), None)
        if not isinstance(s, str):
            # attempt to cast
            try:
                return (float(s), None)
            except Exception:
                return (np.nan, None)

        txt = s.strip().lower()
        # detect unit
        unit = None
        if 'kg' in txt:
            unit = 'kg'
        elif 'lb' in txt or 'pound' in txt:
            unit = 'lb'

        # remove commas
        txt_clean = txt.replace(',', '')
        # extract first numeric token (handles "154 lbs", "70kg", "60.5")
        m = re.search(r'[-+]?\d*\.?\d+|\d+', txt_clean)
        if not m:
            return (np.nan, unit)
        num_str = m.group(0)
        try:
            val = float(num_str)
        except Exception:
            return (np.nan, unit)

        return (val, unit)

    weights_parsed = []
    for s in weights_raw:
        val, unit = parse_weight(s)
        if math.isnan(val):
            weights_parsed.append(np.nan)
            continue
        # convert lb -> kg if requested
        if unit == 'lb' and convert_lbs_to_kg:
            val = val * 0.45359237
        # If no unit but conversion requested, we don't convert (assume numeric already in desired unit)
        weights_parsed.append(float(val))

    # Prepare arrays and filter out entries where weight or height is NaN / invalid
    weights_arr = np.array(weights_parsed, dtype=float)
    heights_arr = np.array(heights, dtype=float)

    mask = ~np.isnan(weights_arr) & ~np.isnan(heights_arr)
    if not mask.any():
        raise ValueError("No valid weight-height pairs after parsing")

    weights_clean = weights_arr[mask]
    heights_clean = heights_arr[mask]

    # Use Plotly to create interactive scatter
    fig = px.scatter(
        x=heights_clean,
        y=weights_clean,
        labels={'x': 'Height', 'y': 'Weight'},
        title='Weight vs Height (weights parsed from strings)',
        hover_data={'Height': heights_clean, 'Weight': weights_clean}
    )
    # Make axis labels clearer
    fig.update_layout(xaxis_title='Height', yaxis_title='Weight')

    if show:
        fig.show()

    return {'weights_kg': weights_parsed, 'heights': heights, 'fig': fig}

# Example usage:
# plot_weights_vs_height()  # uses default dataset and shows an interactive Plotly scatter
# custom = {'Weight_String': ['72kg','155 lb','68.2'], 'Height':[178,170,165]}
# plot_weights_vs_height(custom, convert_lbs_to_kg=True)
```

Notes:
- The function uses Plotly (plotly.express) to plot rather than matplotlib.
- It does simple parsing: extracts the first numeric substring and detects 'kg' and 'lb'/'lbs' to optionally convert pounds to kilograms.
- Unparseable items are set to NaN and filtered out before plotting; a ValueError is raised if no valid pairs remain.

Below is a single self-contained Python function (no pandas) that reads a CSV file, converts number-like strings that may include commas (thousands separators or European decimal commas) into floats, computes mean and sample standard deviation for each numerical column, saves a histogram for each numerical column, and performs a one-way ANOVA across numerical columns when appropriate.

Usage notes:
- The function uses the standard csv module to read the file, numpy for numeric operations, matplotlib for plotting, and scipy for ANOVA.
- It heuristically handles numeric strings like "1,234.56", "1.234,56", "1234,56", and "1,234".
- Histograms are saved to the output directory (created if needed). You can disable showing plots in interactive mode with show_plots=False.
- The function returns a dictionary with means, stds, counts, and ANOVA results (if performed).

Code:

```python
def analyze_csv_numerical(csv_path, output_dir="histograms", bins=30, show_plots=False, min_numeric_ratio=0.5):
    """
    Read CSV at csv_path, convert numeric-looking strings (including those with commas) to floats,
    compute mean and sample standard deviation (ddof=1) for each numerical column, save histograms
    for each numerical column to output_dir, and perform one-way ANOVA across numerical columns
    (if at least two columns have >=2 numeric observations).

    Parameters:
    - csv_path: path to input CSV file
    - output_dir: directory where histogram PNGs will be saved
    - bins: number of histogram bins
    - show_plots: if True, call plt.show() for each histogram (useful interactively)
    - min_numeric_ratio: minimum fraction of non-empty entries that must parse as numbers for a column
                         to be considered numeric (default 0.5)

    Returns:
    A dict with keys:
    - 'means': {colname: mean}
    - 'stds': {colname: std (ddof=1)}
    - 'counts': {colname: number of numeric values}
    - 'anova': {'F': value, 'p': value, 'groups_included': [colnames]} or None if ANOVA not performed
    - 'numeric_columns': [colnames]
    """
    import os
    import csv
    import math
    import re
    from collections import defaultdict
    try:
        import numpy as np
    except Exception as e:
        raise ImportError("numpy is required for this function") from e
    try:
        import matplotlib.pyplot as plt
    except Exception as e:
        raise ImportError("matplotlib is required for this function") from e
    try:
        from scipy import stats
    except Exception as e:
        raise ImportError("scipy is required for ANOVA (scipy.stats.f_oneway)") from e

    # Helper: sanitize filename
    def _sanitize_filename(s):
        return re.sub(r'[^0-9A-Za-z._-]', '_', s)

    # Helper: parse numeric strings robustly (handles thousands separators and European decimals)
    def parse_number_token(token):
        if token is None:
            return None
        s = token.strip()
        if s == '':
            return None
        # Remove currency symbols and spaces inside numbers
        s = s.replace('\u00A0', '')  # non-breaking space
        s = s.replace(' ', '')
        # If contains both '.' and ',', assume ',' is thousands separator -> remove commas
        if '.' in s and ',' in s:
            s2 = s.replace(',', '')
            try:
                return float(s2)
            except ValueError:
                return None
        # If only comma present: could be decimal comma or thousands separators
        if ',' in s and '.' not in s:
            parts = s.split(',')
            # If multiple commas and groups of 3 digits after each comma -> probably thousands separators
            if len(parts) > 1 and all(len(p) == 3 for p in parts[1:]):
                s2 = s.replace(',', '')
                try:
                    return float(s2)
                except ValueError:
                    return None
            # If single comma and the right side length is 1-3, ambiguous:
            # Treat as decimal comma when right part length <=2 (common decimals), else as thousands
            if len(parts) == 2 and len(parts[1]) <= 2:
                s2 = s.replace(',', '.')
                try:
                    return float(s2)
                except ValueError:
                    return None
            # Otherwise remove commas
            s2 = s.replace(',', '')
            try:
                return float(s2)
            except ValueError:
                return None
        # No comma: attempt direct float conversion (may contain percent or other suffix)
        # Remove percent sign and handle it
        is_percent = s.endswith('%')
        if is_percent:
            s = s[:-1]
        # Remove common grouping apostrophe
        s = s.replace("'", "")
        try:
            v = float(s)
            if is_percent:
                return v / 100.0
            return v
        except ValueError:
            # Try to extract number from string, e.g., leading numbers
            m = re.search(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', s)
            if m:
                try:
                    return float(m.group(0))
                except ValueError:
                    return None
            return None

    # Read CSV: detect header and delimiter
    with open(csv_path, newline='', encoding='utf-8') as f:
        sample = f.read(8192)
        f.seek(0)
        sniffer = csv.Sniffer()
        try:
            dialect = sniffer.sniff(sample)
        except Exception:
            dialect = csv.excel
        has_header = sniffer.has_header(sample)
        reader = csv.reader(f, dialect)
        rows = list(reader)

    if not rows:
        raise ValueError("CSV file is empty")

    # Determine header and data rows
    if has_header:
        header = rows[0]
        data_rows = rows[1:]
    else:
        # create generic headers
        ncols = len(rows[0])
        header = [f"col_{i}" for i in range(ncols)]
        data_rows = rows

    num_cols = len(header)
    # Ensure row length consistency: pad/trim rows
    normalized_rows = []
    for r in data_rows:
        if len(r) < num_cols:
            r = r + [''] * (num_cols - len(r))
        elif len(r) > num_cols:
            r = r[:num_cols]
        normalized_rows.append(r)

    # Parse each column
    col_values = defaultdict(list)
    col_numeric_count = defaultdict(int)
    col_nonempty_count = defaultdict(int)

    for r in normalized_rows:
        for i, raw in enumerate(r):
            col = header[i]
            if raw is None:
                continue
            raw_str = raw.strip()
            if raw_str == '':
                continue
            col_nonempty_count[col] += 1
            val = parse_number_token(raw_str)
            if val is not None and (isinstance(val, float) or isinstance(val, int)) and (not math.isnan(val)):
                col_values[col].append(float(val))
                col_numeric_count[col] += 1
            else:
                # not numeric: skip, but keep nonempty count already incremented
                pass

    # Decide which columns are numeric based on min_numeric_ratio and at least 2 numeric values
    numeric_columns = []
    for col in header:
        nonempty = col_nonempty_count.get(col, 0)
        numeric = col_numeric_count.get(col, 0)
        ratio = (numeric / nonempty) if nonempty > 0 else 0.0
        if numeric >= 2 and ratio >= min_numeric_ratio:
            numeric_columns.append(col)

    # Compute statistics
    means = {}
    stds = {}
    counts = {}
    for col in numeric_columns:
        arr = np.array(col_values[col], dtype=float)
        # drop NaNs
        arr = arr[~np.isnan(arr)]
        if arr.size == 0:
            continue
        means[col] = float(np.mean(arr))
        # sample standard deviation ddof=1 when possible; if only one value, std=0
        if arr.size > 1:
            stds[col] = float(np.std(arr, ddof=1))
        else:
            stds[col] = 0.0
        counts[col] = int(arr.size)

    # Prepare output directory
    os.makedirs(output_dir, exist_ok=True)

    # Generate histograms
    for col in numeric_columns:
        data = np.array(col_values[col], dtype=float)
        data = data[~np.isnan(data)]
        if data.size == 0:
            continue
        plt.figure()
        plt.hist(data, bins=bins, color='C0', edgecolor='black')
        plt.title(f"Histogram of {col}")
        plt.xlabel(col)
        plt.ylabel("Frequency")
        fname = os.path.join(output_dir, _sanitize_filename(f"{col}_hist.png"))
        plt.tight_layout()
        plt.savefig(fname, dpi=150)
        if show_plots:
            plt.show()
        plt.close()

    # Perform ANOVA across numeric columns if applicable
    anova_result = None
    # include groups with at least 2 observations
    anova_groups = [np.array(col_values[col], dtype=float)[~np.isnan(col_values[col])] if False else None for col in []]  # placeholder to satisfy lint
    anova_groups = []
    anova_cols_included = []
    for col in numeric_columns:
        arr = np.array(col_values[col], dtype=float)
        arr = arr[~np.isnan(arr)]
        if arr.size >= 2:
            anova_groups.append(arr)
            anova_cols_included.append(col)
    if len(anova_groups) >= 2:
        try:
            F, p = stats.f_oneway(*anova_groups)
            anova_result = {'F': float(F), 'p': float(p), 'groups_included': list(anova_cols_included)}
        except Exception as e:
            anova_result = {'error': f"ANOVA failed: {e}", 'groups_included': list(anova_cols_included)}
    else:
        anova_result = None

    # Prepare return dict
    result = {
        'means': means,
        'stds': stds,
        'counts': counts,
        'anova': anova_result,
        'numeric_columns': numeric_columns
    }

    # Print a short summary
    print("Numerical columns detected:", numeric_columns)
    for col in numeric_columns:
        print(f" - {col}: count={counts.get(col,0)}, mean={means.get(col,'N/A')}, std={stds.get(col,'N/A')} (hist saved to {output_dir})")
    if anova_result is None:
        print("ANOVA not performed (need at least two numeric columns with >=2 observations each).")
    else:
        if 'error' in anova_result:
            print("ANOVA error:", anova_result['error'])
        else:
            print(f"ANOVA result across columns {anova_result['groups_included']}: F={anova_result['F']:.4g}, p={anova_result['p']:.4g}")

    return result
```

