Below is a single, self-contained Python function that reads a CSV without using pandas (it uses the csv module + numpy + scipy + matplotlib instead), converts number-like strings that use commas (thousands separators or decimal commas) into floats, computes mean and standard deviation for each numerical column, saves a histogram for each numeric column, and runs a one-way ANOVA across numeric columns if possible.

Notes:
- The function uses heuristics to interpret comma usage in numbers (handles "1,234.56", "1.234,56", and simple locale cases).
- By default histograms are saved into a "plots" directory; you can show plots interactively instead by setting save_plots=False and show_plots=True.
- Requires numpy, scipy, and matplotlib installed.

Code:

```python
def analyze_csv_numerical(
    file_path,
    save_plots=True,
    output_dir="plots",
    show_plots=False,
    histogram_bins="auto"
):
    """
    Analyze numerical data from a CSV file without pandas.

    - Reads CSV using csv.DictReader.
    - Converts numeric-looking strings with commas into floats (supports thousands separators and decimal-comma heuristics).
    - Computes mean and sample standard deviation (ddof=1) for each numerical column.
    - Generates and either saves or shows a histogram plot for each numerical column.
    - Performs one-way ANOVA across numerical columns (if there are >=2 groups with >=2 observations).

    Parameters:
    - file_path: str, path to CSV file.
    - save_plots: bool, whether to save histogram images (default True).
    - output_dir: str, directory to save plots (created if necessary).
    - show_plots: bool, whether to call plt.show() for each histogram (useful in interactive environments).
                 If save_plots is True but show_plots False, a non-interactive backend is used so this works on servers.
    - histogram_bins: bins argument passed to plt.hist (default "auto").

    Returns:
    dict with keys:
        - "means": {colname: mean}
        - "stds": {colname: std (ddof=1)}
        - "counts": {colname: N}
        - "hist_paths": {colname: path or None}
        - "anova": {"F": float, "p": float} or None if ANOVA couldn't be performed
        - "numeric_columns": list of column names treated as numeric
    """
    import os
    import csv
    import math
    import re

    # Lazy imports for numeric/stats/plotting
    import numpy as np
    try:
        from scipy import stats
    except Exception:
        stats = None
    import matplotlib

    # If we're saving plots non-interactively, switch to Agg backend so it works on headless servers
    if save_plots and not show_plots:
        try:
            matplotlib.use("Agg")
        except Exception:
            pass
    import matplotlib.pyplot as plt

    # Helper: sanitize filenames
    def _safe_name(s):
        s = str(s)
        s = re.sub(r"[^\w\-\.]", "_", s)
        return s[:200]

    # Heuristic parser for numbers containing commas and/or dots
    def _parse_number_token(tok):
        if tok is None:
            return None
        s = str(tok).strip()
        if s == "":
            return None
        # Promote common null markers to None
        if s.lower() in {"na", "n/a", "nan", "null", "none", "-"}:
            return None

        # If it already looks like a plain float/int
        try:
            return float(s)
        except Exception:
            pass

        # Now try heuristics for comma/dot formats
        # Remove spaces and NBSPs
        s = s.replace("\u00A0", "").replace(" ", "")

        # If both '.' and ',' appear, decide which is decimal based on last occurrence
        if "." in s and "," in s:
            if s.rfind(",") > s.rfind("."):
                # comma likely decimal separator: remove dots (thousands), replace comma with dot
                cand = s.replace(".", "").replace(",", ".")
            else:
                # dot likely decimal separator: remove commas (thousands)
                cand = s.replace(",", "")
            try:
                return float(cand)
            except Exception:
                return None

        # Only comma present
        if "," in s and "." not in s:
            # If the part after the final comma has 3 digits and the string length is longer than 4,
            # it's more likely a thousands separator (e.g. "1,234" -> 1234).
            parts_after = s.rsplit(",", 1)[-1]
            if len(parts_after) == 3 and len(s) > 4:
                cand = s.replace(",", "")
                try:
                    return float(cand)
                except Exception:
                    pass
            # Otherwise treat comma as decimal separator
            cand = s.replace(",", ".")
            try:
                return float(cand)
            except Exception:
                # fallback: remove all commas and try
                try:
                    return float(s.replace(",", ""))
                except Exception:
                    return None

        # Only dot present but initial float conversion failed (maybe containing grouping like "1.234")
        if "." in s and "," not in s:
            # If the part after the last dot has 3 digits and the string length > 4, it could be a thousands separator
            parts_after = s.rsplit(".", 1)[-1]
            if len(parts_after) == 3 and len(s) > 4:
                cand = s.replace(".", "")
                try:
                    return float(cand)
                except Exception:
                    pass
            # otherwise we've already tried float(s) earlier; fail
        # If nothing worked, return None
        return None

    # Read csv
    with open(file_path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        rows = list(reader)

    if not rows:
        return {
            "means": {},
            "stds": {},
            "counts": {},
            "hist_paths": {},
            "anova": None,
            "numeric_columns": [],
        }

    headers = reader.fieldnames if reader.fieldnames is not None else list(rows[0].keys())

    # Parse columns: build list of numeric values per column
    col_values = {h: [] for h in headers}
    for r in rows:
        for h in headers:
            raw = r.get(h, "")
            val = _parse_number_token(raw)
            if val is not None and (not (isinstance(val, float) and math.isnan(val))):
                col_values[h].append(val)

    # Identify numeric columns: those with at least one numeric value
    numeric_columns = [h for h, vals in col_values.items() if len(vals) > 0]

    means = {}
    stds = {}
    counts = {}
    hist_paths = {}

    if save_plots and not os.path.exists(output_dir):
        os.makedirs(output_dir, exist_ok=True)

    for h in numeric_columns:
        arr = np.array(col_values[h], dtype=float)
        counts[h] = int(arr.size)
        # mean and sample std (ddof=1). If only one value, std is NaN.
        means[h] = float(np.nanmean(arr)) if arr.size > 0 else float("nan")
        stds[h] = float(np.nanstd(arr, ddof=1)) if arr.size > 1 else float("nan")

        # Plot histogram
        fig, ax = plt.subplots()
        ax.hist(arr, bins=histogram_bins, color="#4C72B0", edgecolor="black")
        ax.set_title(f"Histogram: {h}")
        ax.set_xlabel("Value")
        ax.set_ylabel("Frequency")
        ax.grid(True, linestyle=":", linewidth=0.5, alpha=0.7)

        safe = _safe_name(h)
        path = None
        if save_plots:
            path = os.path.join(output_dir, f"histogram_{safe}.png")
            try:
                fig.tight_layout()
                fig.savefig(path, dpi=150)
            except Exception:
                path = None
        if show_plots:
            try:
                plt.show()
            except Exception:
                pass
        # Close figure to free memory
        plt.close(fig)
        hist_paths[h] = path

    # Perform ANOVA if possible (need >=2 groups and each group must have >=2 observations for f_oneway to be meaningful)
    anova_result = None
    if stats is None:
        anova_result = None
    else:
        # Consider only groups with at least 2 observations
        groups = [np.array(col_values[h], dtype=float) for h in numeric_columns if len(col_values[h]) >= 2]
        group_names = [h for h in numeric_columns if len(col_values[h]) >= 2]
        if len(groups) >= 2:
            try:
                F, p = stats.f_oneway(*groups)
                anova_result = {"F": float(F), "p": float(p), "groups_used": group_names}
            except Exception:
                anova_result = None
        else:
            anova_result = None

    return {
        "means": means,
        "stds": stds,
        "counts": counts,
        "hist_paths": hist_paths,
        "anova": anova_result,
        "numeric_columns": numeric_columns,
    }

