Below is a self-contained Python function that fetches a webpage (using httpx if available, otherwise urllib), extracts the contents of all <script> tags using the standard library HTMLParser, and attempts to parse any object-like string(s) inside those scripts as Python dictionaries. Parsing is done safely (no eval) by trying json.loads first, then ast.literal_eval after converting JS null/true/false to Python equivalents. The function also tries to extract balanced {...} substrings from script contents (to handle var foo = { ... }; patterns).

Copy-paste and use as-is.

```python
from typing import List, Dict, Optional
import json
import ast
import re

# Prefer httpx if installed; fall back to urllib
try:
    import httpx
    _HAS_HTTPX = True
except Exception:
    _HAS_HTTPX = False
    import urllib.request

from html.parser import HTMLParser


class _ScriptCollector(HTMLParser):
    """Collect raw text contents of <script>...</script> tags."""
    def __init__(self) -> None:
        super().__init__()
        self._in_script = False
        self._buf = []
        self.scripts: List[str] = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._in_script = True
            self._buf = []

    def handle_endtag(self, tag):
        if tag.lower() == "script" and self._in_script:
            self.scripts.append("".join(self._buf))
            self._in_script = False
            self._buf = []

    def handle_data(self, data):
        if self._in_script:
            self._buf.append(data)


def _balanced_brace_substrings(text: str) -> List[str]:
    """
    Return all substrings in text that are top-level balanced {...} groups.
    This finds candidate JS/Python object literal strings.
    """
    results = []
    stack = []
    start_idx = None
    for i, ch in enumerate(text):
        if ch == '{':
            if not stack:
                start_idx = i
            stack.append('{')
        elif ch == '}':
            if stack:
                stack.pop()
                if not stack and start_idx is not None:
                    results.append(text[start_idx:i + 1])
                    start_idx = None
    return results


def _try_parse_object_literal(s: str) -> Optional[object]:
    """
    Try to parse a string s as JSON or a Python literal (dict/list).
    Returns parsed object on success, otherwise None.
    """
    s_stripped = s.strip().rstrip(';')
    if not s_stripped:
        return None

    # First try JSON (works if keys/strings are double-quoted)
    try:
        return json.loads(s_stripped)
    except Exception:
        pass

    # Replace JS literals with Python equivalents for ast.literal_eval attempt
    s_py_literals = re.sub(r'\bnull\b', 'None', s_stripped, flags=re.IGNORECASE)
    s_py_literals = re.sub(r'\btrue\b', 'True', s_py_literals, flags=re.IGNORECASE)
    s_py_literals = re.sub(r'\bfalse\b', 'False', s_py_literals, flags=re.IGNORECASE)

    # Try ast.literal_eval (safe)
    try:
        return ast.literal_eval(s_py_literals)
    except Exception:
        pass

    # As a last resort, try a minimal single -> double quote swap and json.loads again
    # (useful for simple single-quoted JSON-like strings)
    if "'" in s_stripped and '"' not in s_stripped:
        s_double = s_stripped.replace("'", '"')
        try:
            return json.loads(s_double)
        except Exception:
            pass

    return None


def fetch_and_extract_dicts(url: str, timeout: float = 10.0) -> List[Dict]:
    """
    Fetch the webpage at `url`, find all <script> tag contents, and attempt to
    evaluate strings inside those tags as Python dictionaries.

    Returns a list of dictionaries found. If no dictionaries are parsed, returns [].

    Notes:
    - Uses httpx if available, otherwise urllib.request.
    - Parsing is safe (uses json.loads and ast.literal_eval); no eval().
    - The function searches for balanced {...} substrings within scripts to
      handle patterns like `var cfg = { ... };`.
    """
    # Fetch page
    if _HAS_HTTPX:
        try:
            resp = httpx.get(url, timeout=timeout)
            resp.raise_for_status()
            html = resp.text
        except Exception as e:
            raise RuntimeError(f"Failed to fetch {url} via httpx: {e}")
    else:
        try:
            with urllib.request.urlopen(url, timeout=timeout) as resp:
                bytes_content = resp.read()
                # Try to decode bytes; default to utf-8 with replacement on errors
                html = bytes_content.decode('utf-8', errors='replace')
        except Exception as e:
            raise RuntimeError(f"Failed to fetch {url} via urllib: {e}")

    # Parse <script> tags
    parser = _ScriptCollector()
    parser.feed(html)
    script_texts = parser.scripts

    found_dicts: List[Dict] = []
    seen = set()

    for script in script_texts:
        # If script content looks like JSON or JS object directly, try whole script first
        candidate_whole = script.strip()
        if candidate_whole:
            parsed = _try_parse_object_literal(candidate_whole)
            if isinstance(parsed, dict):
                key = json.dumps(parsed, sort_keys=True, default=str)
                if key not in seen:
                    found_dicts.append(parsed)
                    seen.add(key)
            elif isinstance(parsed, list):
                # If script is an array, include any dict items inside
                for item in parsed:
                    if isinstance(item, dict):
                        key = json.dumps(item, sort_keys=True, default=str)
                        if key not in seen:
                            found_dicts.append(item)
                            seen.add(key)

        # Also try to find balanced {...} substrings and parse them individually
        for substr in _balanced_brace_substrings(script):
            parsed = _try_parse_object_literal(substr)
            if isinstance(parsed, dict):
                key = json.dumps(parsed, sort_keys=True, default=str)
                if key not in seen:
                    found_dicts.append(parsed)
                    seen.add(key)
            elif isinstance(parsed, list):
                for item in parsed:
                    if isinstance(item, dict):
                        key = json.dumps(item, sort_keys=True, default=str)
                        if key not in seen:
                            found_dicts.append(item)
                            seen.add(key)

    return found_dicts


# Example usage:
if __name__ == "__main__":
    test_url = "https://example.com"  # replace with a real page containing script object literals
    try:
        dicts = fetch_and_extract_dicts(test_url)
        print(f"Found {len(dicts)} dict(s):")
        for d in dicts:
            print(d)
    except Exception as exc:
        print("Error:", exc)
```

Notes and limitations:
- This function intentionally avoids executing arbitrary code — it uses json.loads and ast.literal_eval only.
- It uses heuristics to capture common JS object literal patterns; it may fail on complex/minified JavaScript where object literals aren't isolated or where keys are unquoted and contain characters not accepted by Python.
- For robust JavaScript parsing you'd need a JS-aware parser (e.g., a JS engine or specialized JS AST tools), but this function covers many typical cases encountered in <script> tags.

